PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  participant_code TEXT NOT NULL,
  variant TEXT NOT NULL CHECK (variant IN ('connected', 'disconnected')),
  created_at TEXT NOT NULL,
  started_at TEXT,
  ended_at TEXT,
  build_id TEXT NOT NULL
, last_seen_at TEXT, end_reason TEXT, assigned_scenario TEXT);
CREATE TABLE task_runs (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT,
  task_code TEXT NOT NULL,
  started_at TEXT NOT NULL,
  ended_at TEXT,
  result TEXT CHECK (result IN ('unaided', 'aided', 'failed', 'corrupted')),
  was_aided INTEGER NOT NULL DEFAULT 0,
  ease_score INTEGER CHECK (ease_score BETWEEN 1 AND 7),
  ease_reason TEXT,
  moderator_note TEXT,
  corrupted_reason TEXT
);
CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT,
  task_run_id TEXT REFERENCES task_runs(id) ON DELETE SET NULL,
  timestamp TEXT NOT NULL,
  type TEXT NOT NULL,
  screen TEXT,
  action TEXT,
  target TEXT,
  metadata TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE research_control (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  session_id TEXT,
  participant_code TEXT,
  variant TEXT NOT NULL DEFAULT 'disconnected',
  current_task TEXT,
  current_task_run_id TEXT,
  current_screen TEXT NOT NULL DEFAULT '/',
  reset_version INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_task_runs_session ON task_runs(session_id, started_at);
CREATE INDEX idx_events_session ON events(session_id, id);
CREATE INDEX idx_events_task_run ON events(task_run_id, id);
CREATE INDEX idx_sessions_presence ON sessions(ended_at, last_seen_at);
CREATE UNIQUE INDEX idx_task_runs_active_interactive_session ON task_runs(session_id)
  WHERE ended_at IS NULL AND task_code IN ('CARD_COPY', 'CASHBACK_CONNECT', 'CASHBACK_NEXT');
